require __DIR__.'/../../config/database.php';require __DIR__.'/../../config/helpers.php';if(!isset($_SESSION['ID_USER'])){header('Location: /index.php');exit;}requireRole(0);$lab=max(1,min(4,(int)($_GET['lab']??1)));$s=$con->prepare('SELECT o.ID_OCORR,o.titulo,o.descricao,o.data_ocorr,o.ID_MAQ,o.tipo_problema,o.status_ocorrencia,u.nome AS reportado_por FROM Ocorrencias o JOIN Usuarios u ON u.ID_USER=o.ID_USER WHERE o.ID_LAB=? ORDER BY o.data_ocorr DESC,o.ID_OCORR DESC');$s->bind_param('i',$lab);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();if(!$rows){header('Location: /suporte/relatorio_geral.php?lab='.$lab);exit;}$pdf=new SimplePdf();desenharRelatorioLaboratorioPdf($pdf,$lab,$rows,date('d/m/Y H:i'));$pdf->download('relatorio-laboratorio-'.$lab.'.pdf');
